package org.tabata.timber.core.timer

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue
import kotlin.test.assertIs
import kotlinx.coroutines.test.runTest
import org.tabata.timber.domain.models.TimerState
import org.tabata.timber.domain.models.timer.PhaseType
import org.tabata.timber.domain.models.timer.TimerConfiguration

class TimerControllerTest {
    
    private fun createMockTimerEngine(): MockTimerEngine = MockTimerEngine()
    
    @Test\n    fun testStartSessionSuccess() = runTest {\n        val mockEngine = createMockTimerEngine()\n        val controller = TimerController(mockEngine)\n        val config = TimerConfiguration.createStandard()\n        \n        val result = controller.startSession(config)\n        \n        assertIs<TimerController.TimerOperationResult.Success>(result)\n        assertTrue(mockEngine.startSessionCalled)\n    }\n    \n    @Test\n    fun testStartSessionInvalidState() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.WORK) // Not IDLE\n        val controller = TimerController(mockEngine)\n        val config = TimerConfiguration.createStandard()\n        \n        val result = controller.startSession(config)\n        \n        assertIs<TimerController.TimerOperationResult.Error>(result)\n        assertEquals(TimerController.TimerErrorCode.INVALID_STATE, result.errorCode)\n        assertTrue(result.message.contains(\"Must be IDLE\"))\n    }\n    \n    @Test\n    fun testStartSessionInvalidConfiguration() = runTest {\n        val mockEngine = createMockTimerEngine()\n        val controller = TimerController(mockEngine)\n        val invalidConfig = TimerConfiguration(\n            workDuration = 0, // Invalid - below minimum\n            restDuration = 10,\n            cycles = 1,\n            sets = 1,\n            setBreakDuration = 60\n        )\n        \n        val result = controller.startSession(invalidConfig)\n        \n        assertIs<TimerController.TimerOperationResult.Error>(result)\n        assertEquals(TimerController.TimerErrorCode.INVALID_CONFIGURATION, result.errorCode)\n    }\n    \n    @Test\n    fun testPauseSessionSuccess() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.WORK)\n        mockEngine.setIsActive(true)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.pauseSession()\n        \n        assertIs<TimerController.TimerOperationResult.Success>(result)\n        assertTrue(mockEngine.pauseSessionCalled)\n    }\n    \n    @Test\n    fun testPauseSessionNoActiveSession() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setIsActive(false) // No active session\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.pauseSession()\n        \n        assertIs<TimerController.TimerOperationResult.Error>(result)\n        assertEquals(TimerController.TimerErrorCode.SESSION_NOT_FOUND, result.errorCode)\n    }\n    \n    @Test\n    fun testPauseSessionAlreadyPaused() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.PAUSED)\n        mockEngine.setIsActive(true)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.pauseSession()\n        \n        assertIs<TimerController.TimerOperationResult.Error>(result)\n        assertEquals(TimerController.TimerErrorCode.INVALID_STATE, result.errorCode)\n        assertTrue(result.message.contains(\"already paused\"))\n    }\n    \n    @Test\n    fun testResumeSessionSuccess() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.PAUSED)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.resumeSession()\n        \n        assertIs<TimerController.TimerOperationResult.Success>(result)\n        assertTrue(mockEngine.resumeSessionCalled)\n    }\n    \n    @Test\n    fun testResumeSessionNotPaused() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.WORK) // Not paused\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.resumeSession()\n        \n        assertIs<TimerController.TimerOperationResult.Error>(result)\n        assertEquals(TimerController.TimerErrorCode.INVALID_STATE, result.errorCode)\n        assertTrue(result.message.contains(\"Must be PAUSED\"))\n    }\n    \n    @Test\n    fun testStopSessionSuccess() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setIsActive(true)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.stopSession()\n        \n        assertIs<TimerController.TimerOperationResult.Success>(result)\n        assertTrue(mockEngine.stopSessionCalled)\n    }\n    \n    @Test\n    fun testStopSessionNoActiveSession() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setIsActive(false)\n        mockEngine.setTimerState(TimerState.IDLE)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.stopSession()\n        \n        assertIs<TimerController.TimerOperationResult.Error>(result)\n        assertEquals(TimerController.TimerErrorCode.SESSION_NOT_FOUND, result.errorCode)\n    }\n    \n    @Test\n    fun testSkipToNextSuccess() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.WORK)\n        mockEngine.setIsActive(true)\n        mockEngine.setCurrentPhase(PhaseType.WORK)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.skipToNext()\n        \n        assertIs<TimerController.TimerOperationResult.Success>(result)\n        assertTrue(mockEngine.skipToNextCalled)\n    }\n    \n    @Test\n    fun testSkipToNextInvalidState() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.PAUSED)\n        mockEngine.setIsActive(true)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.skipToNext()\n        \n        assertIs<TimerController.TimerOperationResult.Error>(result)\n        assertEquals(TimerController.TimerErrorCode.INVALID_STATE, result.errorCode)\n        assertTrue(result.message.contains(\"while paused\"))\n    }\n    \n    @Test\n    fun testSkipToNextNotAllowedInCooldown() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.REST) // Will be treated as cooldown phase\n        mockEngine.setCurrentPhase(PhaseType.COOLDOWN)\n        mockEngine.setIsActive(true)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.skipToNext()\n        \n        assertIs<TimerController.TimerOperationResult.Error>(result)\n        assertEquals(TimerController.TimerErrorCode.OPERATION_NOT_ALLOWED, result.errorCode)\n        assertTrue(result.message.contains(\"Cannot skip cooldown\"))\n    }\n    \n    @Test\n    fun testSkipToPreviousSuccess() = runTest {\n        val mockEngine = createMockTimerEngine()\n        mockEngine.setTimerState(TimerState.WORK)\n        mockEngine.setIsActive(true)\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.skipToPrevious()\n        \n        assertIs<TimerController.TimerOperationResult.Success>(result)\n        assertTrue(mockEngine.skipToPreviousCalled)\n    }\n    \n    @Test\n    fun testGetCurrentSessionInfoWithActiveSession() {\n        val mockEngine = createMockTimerEngine()\n        val config = TimerConfiguration.createStandard()\n        \n        mockEngine.setCurrentConfiguration(config)\n        mockEngine.setCurrentSession(mockEngine.createMockSession())\n        mockEngine.setCurrentPhase(PhaseType.WORK)\n        mockEngine.setTimerState(TimerState.WORK)\n        mockEngine.setElapsedTimeMs(15000L)\n        mockEngine.setRemainingTimeMs(5000L)\n        mockEngine.setCurrentCycle(1)\n        mockEngine.setCurrentSet(1)\n        \n        val controller = TimerController(mockEngine)\n        val sessionInfo = controller.getCurrentSessionInfo()\n        \n        assertNotNull(sessionInfo)\n        assertEquals(PhaseType.WORK, sessionInfo.currentPhase)\n        assertEquals(TimerState.WORK, sessionInfo.currentState)\n        assertEquals(15000L, sessionInfo.elapsedTimeMs)\n        assertEquals(5000L, sessionInfo.remainingTimeMs)\n        assertEquals(1, sessionInfo.currentCycle)\n        assertEquals(1, sessionInfo.currentSet)\n    }\n    \n    @Test\n    fun testGetCurrentSessionInfoWithoutSession() {\n        val mockEngine = createMockTimerEngine()\n        val controller = TimerController(mockEngine)\n        \n        val sessionInfo = controller.getCurrentSessionInfo()\n        \n        assertNull(sessionInfo)\n    }\n    \n    @Test\n    fun testSessionInfoProgressCalculation() {\n        val mockEngine = createMockTimerEngine()\n        val config = TimerConfiguration(\n            workDuration = 20,\n            restDuration = 10,\n            cycles = 1,\n            sets = 1,\n            setBreakDuration = 0,\n            warmupDuration = 0,\n            cooldownDuration = 0\n        ) // Total: 30 seconds\n        \n        mockEngine.setCurrentConfiguration(config)\n        mockEngine.setCurrentSession(mockEngine.createMockSession())\n        mockEngine.setElapsedTimeMs(15000L) // 15 seconds elapsed out of 30\n        \n        val controller = TimerController(mockEngine)\n        val sessionInfo = controller.getCurrentSessionInfo()\n        \n        assertNotNull(sessionInfo)\n        assertEquals(50.0, sessionInfo.getProgressPercent()) // 15/30 * 100 = 50%\n    }\n    \n    @Test\n    fun testSessionInfoFormattedTime() {\n        val mockEngine = createMockTimerEngine()\n        val config = TimerConfiguration.createStandard()\n        \n        mockEngine.setCurrentConfiguration(config)\n        mockEngine.setCurrentSession(mockEngine.createMockSession())\n        mockEngine.setRemainingTimeMs(125000L) // 2 minutes 5 seconds\n        \n        val controller = TimerController(mockEngine)\n        val sessionInfo = controller.getCurrentSessionInfo()\n        \n        assertNotNull(sessionInfo)\n        assertEquals(\"02:05\", sessionInfo.getFormattedRemainingTime())\n    }\n    \n    @Test\n    fun testErrorCodeEnumValues() {\n        val errorCodes = TimerController.TimerErrorCode.values()\n        \n        assertTrue(errorCodes.contains(TimerController.TimerErrorCode.INVALID_STATE))\n        assertTrue(errorCodes.contains(TimerController.TimerErrorCode.INVALID_CONFIGURATION))\n        assertTrue(errorCodes.contains(TimerController.TimerErrorCode.SESSION_NOT_FOUND))\n        assertTrue(errorCodes.contains(TimerController.TimerErrorCode.OPERATION_NOT_ALLOWED))\n        assertTrue(errorCodes.contains(TimerController.TimerErrorCode.INTERNAL_ERROR))\n    }\n    \n    @Test\n    fun testResetTimerSuccess() = runTest {\n        val mockEngine = createMockTimerEngine()\n        val controller = TimerController(mockEngine)\n        \n        val result = controller.resetTimer()\n        \n        assertIs<TimerController.TimerOperationResult.Success>(result)\n        assertTrue(mockEngine.resetTimerCalled)\n    }\n}\n\n// Helper methods for session info testing would go here if needed\n// Additional integration tests could be added for complex state transitions"